class Cart:
    def __init__(self, owner, items=[]):
        self.owner = owner
        self.items = items

    def add_item(self, name):
        self.items.append(name)

    def item_count(self):
        return len(self.items)

class Cart:
    def __init__(self, owner, items=None):
        self.owner = owner
        self.items = [] if items is None else list(items)

    def add_item(self, name):
        self.items.append(name)

    def item_count(self):
        return len(self.items)

